 static final String SECOND="cc000000-0000-4000-8000-000000000001",AREA="dd000000-0000-4000-8000-000000000001",INVOICE="ee000000-0000-4000-8000-000000000001";
 static Map<String,Object> configurationRoot(){var r=plan();r.remove("currentVersion");r.remove("description");r.put("id",TENANT);r.put("tenantId",TENANT);r.put("name","Synthetic organization");r.put("planName","Historical plan");r.put("planVersion",3);r.put("version",3);r.put("slug","synthetic-clinic");r.put("kind","CLINIC");r.put("domain","HUMAN");r.put("status","SUSPENDED");r.put("timezone","America/Lima");r.put("cycle","YEARLY");r.put("branchQuota",1);r.put("professionalQuota",1);r.put("specialtyQuota",1);r.put("renewalDate","2028-02-29");return r;}
 static Map<String,Object> configurationInvoice(){var r=new LinkedHashMap<String,Object>();r.put("id",INVOICE);r.put("tenantId",TENANT);r.put("amountMinor",Long.MAX_VALUE);r.put("currency","USD");r.put("cycle","CUSTOM");r.put("status","PAID");r.put("createdAt",TIME);r.put("paidAt",null);return r;}
 static List<List<Map<String,Object>>> configurationSets() throws Exception {var root=configurationRoot();var branch=new LinkedHashMap<>(directory());branch.put("tenantId",TENANT);branch.put("active",false);var specialty=realSpecialty();String code=(String)specialty.get("code");var area=new LinkedHashMap<String,Object>(Map.of("id",AREA,"tenantId",TENANT,"branchId",ID,"name","Consulta","specialties",List.of(code)));var member=identity();member.put("roles",List.of("ADM","PRO"));member.put("status","ACTIVE");member.put("owner",true);var other=new LinkedHashMap<>(member);other.put("id",SECOND);other.put("roles",List.of("REC"));other.put("status","INACTIVE");other.put("owner",false);var sets=new ArrayList<List<Map<String,Object>>>();sets.add(new ArrayList<>(List.of(root)));sets.add(new ArrayList<>(List.of(branch)));sets.add(new ArrayList<>(List.of(area)));sets.add(new ArrayList<>(List.of(specialty)));sets.add(new ArrayList<>(List.of(member,other)));sets.add(new ArrayList<>(List.of(new LinkedHashMap<>(Map.of("userId",ID,"branchId",ID)))));sets.add(new ArrayList<>(List.of(new LinkedHashMap<>(Map.of("userId",ID,"specialtyCode",code)))));sets.add(new ArrayList<>(List.of(configurationInvoice())));return sets;}
 void config(List<List<Map<String,Object>>> sets){results.add(new SqlServerExecutor.Result(sets,List.of(0)));}
 @Test void configurationEightSetsProduce36RootAnd10MemberFieldsWithoutNPlusOne() throws Exception {var sets=configurationSets();assertEquals(31,sets.getFirst().getFirst().size());for(var rows:sets)for(var row:rows)row.put("private","canary");config(sets);var out=store.configuration(request,null);assertEquals(36,out.size());assertEquals(TENANT,out.get("id"));assertEquals(TENANT,out.get("tenantId"));assertEquals(ID,out.get("planId"));assertFalse(out.containsKey("currentVersion"));assertEquals(List.of(SqlServerProcedure.ORGANIZATION_CONFIGURATION),calls);assertEquals(List.of(TENANT),args.getFirst());var branches=(List<Map<String,Object>>)out.get("branches");assertEquals(6,branches.getFirst().size());assertEquals(false,branches.getFirst().get("active"));var members=(List<Map<String,Object>>)out.get("members");assertEquals(10,members.getFirst().size());assertEquals(List.of(ID),members.getFirst().get("branches"));assertEquals(List.of(),members.get(1).get("branches"));assertEquals(List.of(),members.get(1).get("specialties"));assertNull(members.getFirst().get("clinicalDomain"));assertEquals(8,((List<Map<String,Object>>)out.get("invoices")).getFirst().size());assertEquals(Long.MAX_VALUE,((List<Map<String,Object>>)out.get("invoices")).getFirst().get("amountMinor"));assertNull(((List<Map<String,Object>>)out.get("invoices")).getFirst().get("paidAt"));assertFalse(out.toString().contains("canary"));assertThrows(UnsupportedOperationException.class,out::clear);assertThrows(UnsupportedOperationException.class,branches::clear);assertThrows(UnsupportedOperationException.class,members.getFirst()::clear);assertThrows(UnsupportedOperationException.class,((List<?>)members.getFirst().get("branches"))::clear);}
 @Test void configurationRootMissingMultipleForeignAndWrongSetCountsFail() throws Exception {var empty=configurationSets();empty.get(0).clear();config(empty);assertEquals(404,assertThrows(ApiException.class,()->store.configuration(request,null)).status);var duplicate=configurationSets();duplicate.get(0).add(configurationRoot());config(duplicate);safe(()->store.configuration(request,null));for(String key:List.of("id","tenantId")){var rows=configurationSets();rows.get(0).getFirst().put(key,ID);config(rows);safe(()->store.configuration(request,null));}for(int count:List.of(0,7,9)){var sets=new ArrayList<List<Map<String,Object>>>();for(int i=0;i<count;i++)sets.add(List.of());config(sets);safe(()->store.configuration(request,null));}}
